void SMaximumF16Sop2::execute_impl(amdgpu::Wavefront &wf) {
  float result = [&]() {
    float a = util::f16_to_f32(static_cast<uint16_t>(ssrc0.read_scalar(wf)));
    float b = util::f16_to_f32(static_cast<uint16_t>(ssrc1.read_scalar(wf)));
    if (std::isnan(a) || std::isnan(b))
      return std::numeric_limits<float>::quiet_NaN();
    if (a == b)
      return std::signbit(a) ? b : a;
    return a > b ? a : b;
  }();
  sdst.write_scalar(wf, util::f32_to_f16(result));
}

